def longest_pure_segment(dna):
    n = len(dna)
    max_len = 0

    for i in range(n):
        seen = set()
        for j in range(i, n):
            if dna[j] in seen:
                break          # repeat found, stop extending from i
            seen.add(dna[j])
            max_len = max(max_len, j - i + 1)

    return max_len

def max_profit_subarray(profits):
    n = len(profits)
    max_sum = profits[0]
    best_start = 0
    best_end = 0

    for i in range(n):
        current_sum = 0
        for j in range(i, n):
            current_sum += profits[j]
            # Update only if strictly greater (earliest start/end on tie)
            if current_sum > max_sum:
                max_sum = current_sum
                best_start = i
                best_end = j

    return (max_sum, best_start, best_end)

