def max_profit_subarray(profits):
    n = len(profits)
    max_sum = profits[0]       # best sum seen globally
    current_sum = profits[0]   # sum of the current candidate subarray
    best_start = 0             # start index of the best subarray found
    best_end = 0               # end index of the best subarray found
    temp_start = 0             # tentative start of the current subarray

    for i in range(1, n):
        # If starting fresh at i beats extending: reset current window
        if profits[i] > current_sum + profits[i]:
            current_sum = profits[i]
            temp_start = i     # new candidate subarray begins at i
        else:
            current_sum = current_sum + profits[i]

        # Update global best only if strictly better (preserves earliest start)
        if current_sum > max_sum:
            max_sum = current_sum
            best_start = temp_start
            best_end = i

    return (max_sum, best_start, best_end)

