from collections import Counter

def min_coverage_window(feed, alert):
    if not alert or not feed:
        return ""

    alert_count = Counter(alert)
    n = len(feed)
    best = ""

    for i in range(n):
        window_count = Counter()
        for j in range(i, n):
            window_count[feed[j]] += 1
            # Check if window satisfies all alert requirements
            valid = all(window_count[c] >= alert_count[c] for c in alert_count)
            if valid:
                window = feed[i:j+1]
                if best == "" or len(window) < len(best):
                    best = window
                break  # no need to extend further from i; shortest from i found

    return best
